import { attachControl, setCameraLimits } from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const lower = Math.max(0, Math.min(minDistance, maxDistance));
  const upper = Math.max(lower, Math.max(minDistance, maxDistance));

  const clampRadius = (radius: number): number =>
    Math.min(Math.max(radius, lower), upper);

  const previousLower = camera.lowerRadiusLimit;
  const previousUpper = camera.upperRadiusLimit;

  const disposeLimits = setCameraLimits(
    camera,
    { lowerRadiusLimit: lower, upperRadiusLimit: upper },
    scene
  );

  camera.radius = clampRadius(camera.radius);
  camera._clampToLimits?.();

  const disposeControls = attachControl(camera, canvas, scene);

  let disposed = false;
  return () => {
    if (disposed) return;
    disposed = true;
    disposeControls();
    disposeLimits();
    camera.lowerRadiusLimit = previousLower;
    camera.upperRadiusLimit = previousUpper;
  };
}
```

I added a scoped wrapper that clamps the initial radius, uses the library’s `setCameraLimits` for the radius range and `attachControl` for the default orbit/zoom controls, and disposes both while restoring the previous radius limits. I was not 100% sure whether `setCameraLimits` is exported from the package root and whether it itself registers the per-frame clamp, but the provided declarations suggest that is the intended mechanism.

